'use strict';
// Branch-based Pages doesn't run npm. Check in just this small, reproducible
// static build. No recursive copies, environment-provided inputs or remote CDN.
const fs = require('node:fs');
const path = require('node:path');
const esbuild = require('esbuild');
const { buildSample } = require('./pages-fixture');
const root = path.resolve(__dirname, '..');
const abs = f => path.join(root, f);
const read = f => fs.readFileSync(abs(f), 'utf8');
const outputs = new Map();
const add = (name, bytes) => outputs.set(name, Buffer.from(bytes));
const check = process.argv.includes('--check');
const fonts = ['inter-latin-400-normal.woff2','inter-latin-500-normal.woff2','inter-latin-600-normal.woff2','inter-latin-700-normal.woff2','noto-sans-devanagari-wght.woff2'];

async function bundle(entry, outfile, replacements, format) {
  const result = await esbuild.build({ absWorkingDir:root, entryPoints:[entry], outfile, bundle:true, format,
    platform:'browser', target:'es2022', minify:true, charset:'utf8', legalComments:'inline', write:false,
    plugins:[{name:'pages-only-adapters', setup(build) {
      build.onResolve({filter:/.*/}, args => {
        const name = replacements[args.path];
        if (typeof name === 'string') return { path:abs(name) };
      });
    }}], metafile:true });
  // Never ship the Node auth/DB entry, demo login passwords, disk backup logic,
  // or HTTP fallback. Unrecognised Node-only dependencies fail the browser build.
  for (const f of Object.keys(result.metafile.inputs)) {
    if (/^(server\/(?:auth|db|restore-point|seed|index)|public\/js\/(?:views\/login|views\/account|transport))\.js$/.test(f)) throw Error('Unexpected Pages input: '+f);
  }
  add(outfile,result.outputFiles[0].contents);
}
async function build() {
  await bundle('public/js/app.js','docs/workspace.js', {
    './transport.js':'pages-demo/transport.js', './views/login.js':'pages-demo/personas.js', './views/account.js':'pages-demo/personas.js',
  },'esm');
  await bundle('pages-demo/engine.js','docs/engine.js', {
    express:'pages-demo/router.js', './db':'pages-demo/db.js', './auth':'server/permissions.js',
    'node:crypto':'pages-demo/platform.js', './send-workbook':'pages-demo/platform.js', './restore-point':'pages-demo/platform.js', exceljs:'pages-demo/platform.js',
  },'iife');
  add('docs/sample.gz', await buildSample());
  add('docs/sqlite.wasm',fs.readFileSync(require.resolve('sql.js/dist/sql-wasm-browser.wasm')));
  add('docs/workbooks.js',fs.readFileSync(require.resolve('exceljs/dist/exceljs.bare.min.js'),'utf8').replace(/\n\/\/# sourceMappingURL=.*\s*$/, '\n'));
  add('docs/site.css',read('public/css/styles.css').replaceAll("url('/fonts/", "url('./")+'\n'+read('pages-demo/site.css'));
  for (const name of fonts) add('docs/'+name,fs.readFileSync(abs('public/fonts/'+name)));
  add('docs/notices.txt', ['node_modules/sql.js/LICENSE','node_modules/sql.js/AUTHORS','node_modules/exceljs/dist/LICENSE','node_modules/@noble/hashes/LICENSE','public/fonts/Inter-OFL.txt','public/fonts/NotoSansDevanagari-OFL.txt'].map(f => f+'\n\n'+read(f)).join('\n\n'));
  // Both valid publishing settings open the same app (including hash links),
  // with no redirect to GitHub and no duplicate application bundles.
  add('index.html',read('docs/index.html').replaceAll('="./','="./docs/'));
  const names = ['docs','index.html','mark.svg', ...[...outputs.keys()].filter(p => p.startsWith('docs/')).map(p => path.basename(p))].sort();
  // Jekyll gives explicit basename includes priority over excludes. Bracket
  // the first letter to match an exact name, not its string-prefix fallback.
  add('_config.yml', '# Generated by npm run build:pages. For main / (root), publish ONLY the sample app.\n'+
    'theme: null\nreadme_index:\n  enabled: false\nexclude: ["**"]\ninclude: '+JSON.stringify(names.map(n => `[${n[0]}]${n.slice(1)}`))+'\n');
  for (const [name,bytes] of outputs) {
    if (check) {
      if (!fs.existsSync(abs(name)) || !fs.readFileSync(abs(name)).equals(bytes)) throw Error(`Stale ${name}; run npm run build:pages`);
    } else fs.writeFileSync(abs(name), bytes);
  }
  console.log(`${check ? 'Verified' : 'Built'} ${outputs.size} Pages outputs from the approved sample and shared app sources.`);
}
build().catch(e => {console.error(e); process.exitCode=1;});
